<?php
namespace App\Http\Controllers;
use App\Models\Usuario; use App\Models\Rol; use App\Models\Empleado; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class UsuarioController extends Controller {
 public function index(){ $usuarios=Usuario::with(['rol','empleado'])->orderBy('Nombre_Usuario')->paginate(15); return view('usuarios.index',compact('usuarios')); }
 public function create(){ $roles=Rol::orderBy('Nombre')->get(); $empleados=Empleado::where('Estatus','Activo')->orderBy('Nombre')->get(); return view('usuarios.form', ['usuario'=>new Usuario,'roles'=>$roles,'empleados'=>$empleados,'editando'=>false]); }
 public function store(Request $r){ $d=$r->validate(['Nombre_Usuario'=>'required|string|max:50|unique:usuarios,Nombre_Usuario','password'=>'required|string|min:8|confirmed','FkId_Rol'=>'required|exists:roles,Id_Rol','FkId_Empleado'=>'nullable|exists:empleados,Id_Empleado','Estatus'=>'required|in:Activo,Inactivo']); Usuario::create(['Nombre_Usuario'=>$d['Nombre_Usuario'],'Password_Hash'=>Hash::make($d['password']),'FkId_Rol'=>$d['FkId_Rol'],'FkId_Empleado'=>$d['FkId_Empleado']??null,'Estatus'=>$d['Estatus']]); return redirect()->route('usuarios.index')->with('ok','Cuenta creada correctamente.'); }
 public function edit(Usuario $usuario){ $roles=Rol::orderBy('Nombre')->get(); $empleados=Empleado::where('Estatus','Activo')->orderBy('Nombre')->get(); return view('usuarios.form',['usuario'=>$usuario,'roles'=>$roles,'empleados'=>$empleados,'editando'=>true]); }
 public function update(Request $r, Usuario $usuario){ $d=$r->validate(['Nombre_Usuario'=>['required','string','max:50',Rule::unique('usuarios','Nombre_Usuario')->ignore($usuario->Id_Usuario,'Id_Usuario')],'password'=>'nullable|string|min:8|confirmed','FkId_Rol'=>'required|exists:roles,Id_Rol','FkId_Empleado'=>'nullable|exists:empleados,Id_Empleado','Estatus'=>'required|in:Activo,Inactivo']); $usuario->Nombre_Usuario=$d['Nombre_Usuario']; $usuario->FkId_Rol=$d['FkId_Rol']; $usuario->FkId_Empleado=$d['FkId_Empleado']??null; $usuario->Estatus=$d['Estatus']; if(!empty($d['password'])) $usuario->Password_Hash=Hash::make($d['password']); $usuario->save(); return redirect()->route('usuarios.index')->with('ok','Cuenta actualizada.'); }
 public function destroy(Usuario $usuario){ if((int)$usuario->Id_Usuario === (int)auth()->id()) return back()->withErrors(['usuario'=>'No puedes desactivar tu propia cuenta mientras estás dentro.']); $usuario->update(['Estatus'=>'Inactivo']); return back()->with('ok','Cuenta desactivada; su historial se conserva.'); }
}
